head.script:
// 테스트 설명, 유효성 값 설정
//  - 분할 _3 : dataType="time" 축 (속성값 time 항목, 미설정 시 time 기본값, time 마스크 문자 적용 방식)
scwin.tData = {
    "description" : "[column > P > displayFormat]<br/>Column 이 편집 상태가 아닐때 Column 값이 표시되는 포맷을 마스크 문자로 설정합니다.",
    "validation" : [
        "dataType='time' 설정 시, 'H', 'm', 's' 마스크 문자를 사용하여 포맷 설정",
        "displayFormat 속성값을 설정하지 않으면 Column 의 dataType 또는 inputType 값에 따라 다음과 같이 동작합니다. dataType='time' : 'HH:mm'",
        "dataType='time' 일때 'HH' 마스크는 시와 매칭되며 두자리로 설정합니다.",
        "dataType='time' 일때 'mm' 마스크는 분과 매칭되며 두자리로 설정합니다.",
        "dataType='time' 일때 'ss' 마스크는 초와 매칭되며 두자리로 설정합니다.",
        "dataType='time' 일때 마스크 포맷 왼쪽과 오른쪽의 일반문자는 그대로 적용됩니다.",
        "dataType='time' 일때 내부 텍스트는 HHmmss 형식으로 제공되어야 정상적으로 처리됩니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_displayFormat.setValue("HH:mm:ss");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - fmt  : 저장값 형식 안내 Column (readOnly)
//  - ctime: 검증 대상 Column (dataType="time", displayFormat 을 옵션값으로 설정. 미설정 시 속성 자체를 넣지 않는다)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof dlt_time !== 'undefined') {
        $p.data.remove("dlt_time");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 출발 시각 Column 은 dataType=time 고정. 마지막 Row 는 저장값이 HHmmss 형식이 아님\n[확인] displayFormat 선택 -> Target 재생성 -> (셀 표시값 확인) 으로 저장값별 셀 표시값 비교"', '', 'label1');

    // dataList 생성 (body column id 와 동일한 컬럼 id 사용)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_time" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="fmt" name="fmt" dataType="text"></w2:column>';
    strDlt += '<w2:column id="ctime" name="ctime" dataType="time"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_time.setJSON([
        { "fmt" : "HHmmss", "ctime" : "090507" },
        { "fmt" : "HHmmss", "ctime" : "143025" },
        { "fmt" : "HHmmss", "ctime" : "235959" },
        { "fmt" : "HH:mm:ss (HHmmss 아님)", "ctime" : "14:30:25" }
    ], false);

    // ctime Column 속성 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cDisplayFormat = con_displayFormat.getValue();
    let attrTime = ' dataType="time"';
    if (cDisplayFormat !== '') {
        attrTime += ' displayFormat="' + cDisplayFormat + '"';
    }

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_time" checkAllType="false" id="" style="width:500px;height:230px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="220" style="" inputType="text" id="column1" value="저장값 형식"></w2:column>';
    strTarget += '<w2:column width="260" style="" inputType="text" id="column2" value="출발 시각 (time)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="220" style="" inputType="text" id="fmt" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="260" style="" inputType="text" id="ctime" value=""' + attrTime + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 설정한 displayFormat 과 Row 별 저장값 -> 셀 표시값 출력
//  - validation 1, 3, 4, 5, 6 : HHmmss 저장값 Row 의 표시값 (마스크별 시/분/초 두자리, 일반문자 유지)
//  - validation 2 : displayFormat 미설정 시 표시값이 HH:mm 형식인지
//  - validation 7 : HHmmss 형식이 아닌 마지막 Row 의 표시값
scwin.btn_checkCell_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let cDisplayFormat = con_displayFormat.getValue();

    bottom.setReturnValue("displayFormat : " + (cDisplayFormat === '' ? "(미설정)" : cDisplayFormat));

    for (let i = 0; i < dlt_time.getRowCount(); i++) {
        let td = document.querySelector("td[id*='" + target1.id + "_cell_" + i + "_1']");
        bottom.setReturnValue("Row " + i + " 저장값 : " + target1.getCellData(i, "ctime") + " -> 셀 표시값 : " + (td ? td.textContent : ""));
    }
}
